import sys
from collections import deque

class Node:
    def __init__(self, value):
        self.value = value
        self.children = []

def main():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return

    n = int(data[0].strip())
    operations = []
    for i in range(1, n + 1):
        operations.append(data[i].strip())

    root = None
    nodes = {}  # value -> Node

    results = []

    for op in operations:
        parts = op.split()
        if not parts:
            continue

        if parts[0] == 'insert':
            parent_val = int(parts[1])
            child_val = int(parts[2])

            if parent_val not in nodes:
                nodes[parent_val] = Node(parent_val)
                if root is None:
                    root = nodes[parent_val]

            if child_val not in nodes:
                nodes[child_val] = Node(child_val)

            nodes[parent_val].children.append(nodes[child_val])

        elif parts[0] == 'delete':
            val = int(parts[1])
            if val in nodes:
                # BFS to find and mark all nodes for deletion
                to_delete = []
                q = deque([nodes[val]])
                while q:
                    node = q.popleft()
                    to_delete.append(node)
                    for child in node.children:
                        q.append(child)

                for node in to_delete:
                    if node in nodes:
                        del nodes[node.value]

                # Remove deleted node from parent's children
                for v in list(nodes.keys()):
                    for child in nodes[v].children:
                        if child.value == val:
                            nodes[v].children.remove(child)

        elif parts[0] == 'preorder':
            if root is None or root.value not in nodes:
                results.append('')
            else:
                result = []
                stack = [root]
                while stack:
                    node = stack.pop()
                    result.append(str(node.value))
                    for child in reversed(node.children):
                        if child.value in nodes:
                            stack.append(child)
                results.append(' '.join(result))

        elif parts[0] == 'postorder':
            if root is None or root.value not in nodes:
                results.append('')
            else:
                result = []
                stack = [(root, False)]
                while stack:
                    node, visited = stack.pop()
                    if visited:
                        result.append(str(node.value))
                    else:
                        stack.append((node, True))
                        for child in reversed(node.children):
                            if child.value in nodes:
                                stack.append((child, False))
                results.append(' '.join(result))

    for r in results:
        print(r)

if __name__ == "__main__":
    main()
